class MinStack:
    def __init__(self):
        self.st, self.mins = [], []

    def push(self, x):
        self.st.append(x)
        self.mins.append(x if not self.mins else min(x, self.mins[-1]))

    def pop(self):
        self.st.pop(); self.mins.pop()

    def top(self):
        return self.st[-1]

    def get_min(self):
        return self.mins[-1]
